268	    protected void setPetsInternal(Set<Pet> pets) {
269	        this.pets = pets;
270	    }
271	
272	    public List<Pet> getPets() {
273	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
274	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
275	        return Collections.unmodifiableList(sortedPets);
276	    }
277	
278	    public void setPets(List<Pet> pets) {
279	        this.pets = new HashSet<>(pets);
280	    }
281	
282	    public void addPet(Pet pet) {
283	        getPetsInternal().add(pet);
284	        pet.setOwner(this);
285	    }
286	
287	    /**
288	     * Return the Pet with the given name, or null if none found for this Owner.
289	     *
290	     * @param name to test
291	     * @return true if pet name is already in use
292	     */
293	    public Pet getPet(String name) {
294	        return getPet(name, false);
295	    }
296	
297	    /**
298	     * Return the Pet with the given name, or null if none found for this Owner.
299	     *
300	     * @param name to test
301	     * @return true if pet name is already in use
302	     */
303	    public Pet getPet(String name, boolean ignoreNew) {
304	        name = name.toLowerCase();
305	        for (Pet pet : getPetsInternal()) {
306	            if (!ignoreNew || !pet.isNew()) {
307	                String compName = pet.getName();
308	                compName = compName.toLowerCase();
309	                if (compName.equals(name)) {
310	                    return pet;
311	                }
312	            }
313	        }
314	        return null;
315	    }
316	
317	    public Pet getPet(Integer petId) {
318	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
319	    }
320	
321	    @Override
322	    public String toString() {
323	        return new ToStringCreator(this)
324	
325	            .append("id", this.getId())
326	            .append("new", this.isNew())
327	            .append("lastName", this.getLastName())
328	            .append("firstName", this.getFirstName())
329	            .append("address", this.address)
330	            .append("city", this.city)
331	            .append("telephone", this.telephone)
332	            .append("email", this.email)
333	            .toString();
334	    }
335	}
