1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	import java.time.LocalDate;
6	
7	/**
8	 * Scores an owner's membership and maps that score to a numeric level. Points start at zero and
9	 * accrue for each qualifying factor: {@link #EMAIL_POINTS} for a present email,
10	 * {@link #NO_NAMESAKE_POINTS} for having no namesakes ({@code namesakeCount} is 0),
11	 * {@link #HOUSEHOLD_POINTS} for a household of {@link #HOUSEHOLD_SIZE} or more, and
12	 * {@link #TENURE_POINTS} for tenure of at least {@link #TENURE_FISCAL_YEARS} elapsed fiscal
13	 * year(s) since registration (see {@link FiscalYears}). The total is mapped to a level of 1 to 4
14	 * by {@link #levelFor(int)}. A newly created owner has zero tenure, so the tenure points are out
15	 * of reach on creation.
16	 */
17	public final class MembershipLevels {
18	
19	    /** Points added when an email is present. */
20	    public static final int EMAIL_POINTS = 2;
21	
22	    /** Points added when the owner has no namesakes ({@code namesakeCount} is 0). */
23	    public static final int NO_NAMESAKE_POINTS = 1;
24	
25	    /** Points added for a household of {@link #HOUSEHOLD_SIZE} or more. */
26	    public static final int HOUSEHOLD_POINTS = 2;
27	
28	    /** Household size, in members, that must be reached for {@link #HOUSEHOLD_POINTS}. */
29	    public static final int HOUSEHOLD_SIZE = 3;
30	
31	    /** Points added for tenure of at least {@link #TENURE_FISCAL_YEARS} elapsed fiscal year(s). */
32	    public static final int TENURE_POINTS = 3;
33	
34	    /** Elapsed fiscal years since registration required to earn {@link #TENURE_POINTS}. */
35	    public static final int TENURE_FISCAL_YEARS = 1;
36	
37	    private MembershipLevels() {
38	    }
39	
40	    /** Return the membership points for {@code owner} as at {@code asOf}. */
41	    public static int pointsOf(Owner owner, LocalDate asOf) {
42	        int points = 0;
43	        if (owner.hasEmail()) {
44	            points += EMAIL_POINTS;
45	        }
46	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
47	            points += NO_NAMESAKE_POINTS;
48	        }
49	        if (hasHousehold(owner)) {
50	            points += HOUSEHOLD_POINTS;
51	        }
52	        if (hasTenure(owner, asOf)) {
53	            points += TENURE_POINTS;
54	        }
55	        return points;
56	    }
57	
58	    /** Map membership points to a level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
59	    public static int levelFor(int points) {
60	        if (points >= 6) {
61	            return 4;
62	        }
63	        if (points >= 4) {
64	            return 3;
65	        }
66	        if (points >= 2) {
67	            return 2;
68	        }
69	        return 1;
70	    }
71	
72	    /** Whether the owner's household has {@link #HOUSEHOLD_SIZE} or more members. */
73	    private static boolean hasHousehold(Owner owner) {
74	        Integer size = owner.getHouseholdSize();
75	        return size != null && size >= HOUSEHOLD_SIZE;
76	    }
77	
78	    /**
79	     * Whether at least {@link #TENURE_FISCAL_YEARS} fiscal year(s) have elapsed between the owner's
80	     * registration date and {@code asOf}.
81	     */
82	    private static boolean hasTenure(Owner owner, LocalDate asOf) {
83	        LocalDate registration = owner.getRegistrationDate();
84	        if (registration == null || asOf == null) {
85	            return false;
86	        }
87	        return FiscalYears.elapsedBetween(registration, asOf) >= TENURE_FISCAL_YEARS;
88	    }
89	}
