6	/**
7	 * Assigns the owner's household identifier before it is saved. The id is derived from the
8	 * owner's last name and postcode via {@link HouseholdKey#id(String, String)}, so every owner of
9	 * the same household receives the same stable value. Runs after {@link BuildOwner} has produced
10	 * the entity and before {@link SaveOwner} persists it, mutating the built owner in place.
11	 */
12	public class AssignHouseholdId {
13	
14	    public void service(@Val Owner owner) {
15	        owner.setHouseholdId(HouseholdKey.id(owner.getLastName(), owner.getPostcode()));
16	    }
17	}
