1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.HouseholdDuplicateException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create request that would silently join an existing household. A household is keyed
11	 * on (last name, postcode) via {@link HouseholdKey}, so an existing owner sharing this request's
12	 * {@link HouseholdKey#id(String, String) household id} means the same household. Such a request is
13	 * a household duplicate and maps to a 409 — unless it declares {@code sharesHousehold}, in which
14	 * case the owner is knowingly joining the household and is allowed through (created as a declared
15	 * member by the later steps, and not flagged as a possible duplicate).
16	 *
17	 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link BuildOwner} maps the body to an
18	 * entity. Existing owners' household ids are recomputed from their last name and postcode, so a
19	 * match does not depend on any stored value. A household needs a postcode: when the request has
20	 * none, no household can be asserted and the block does not apply.
21	 */
22	public class EnsureUniqueHousehold {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws HouseholdDuplicateException {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	        String postcode = request.getPostcode();
30	        if (postcode == null || postcode.isBlank()) {
31	            return;
32	        }
33	        String householdId = HouseholdKey.id(request.getLastName(), postcode);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (existing.isDeleted()) {
36	                continue; // a soft-deleted owner no longer blocks a matching household
37	            }
38	            if (householdId.equals(HouseholdKey.id(existing.getLastName(), existing.getPostcode()))) {
39	                throw new HouseholdDuplicateException(householdId, existing.getId());
40	            }
41	        }
42	    }
43	}
