3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import java.time.LocalDate;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.util.MembershipLevels;
11	import org.springframework.samples.petclinic.util.MembershipNumbers;
12	
13	/**
14	 * Emits an audit trail line for a newly created owner. Runs after {@link SaveOwner} has
15	 * persisted the entity, so the generated id is available, and records the owner id, the
16	 * assigned customer code, the effective registration date, the derived membership points,
17	 * level and number on the dedicated {@code AUDIT} logger. Purely a side-effect step; it leaves the
18	 * owner unchanged for the responder.
19	 */
20	public class AuditOwnerCreated {
21	
22	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
23	
24	    public void service(@Val Owner owner) {
25	        int points = MembershipLevels.pointsOf(owner, LocalDate.now());
26	        AUDIT.info(
27	                "Owner created: id={} customerCode={} registrationDate={} membershipPoints={} membershipLevel={} membershipNumber={}",
28	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
29	                points, MembershipLevels.levelFor(points), MembershipNumbers.of(owner));
30	    }
31	}
