24	/**
25	 * Maps Owner & OwnerDto using Mapstruct
26	 */
27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
31	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
32	    @Mapping(target = "initials", expression = "java(initials(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
35	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
43	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
44	    @Mapping(target = "sharesHousehold", ignore = true)
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /** The owner's canonical API path, '/api/owners/' followed by its id, or null before an id is assigned. */
48	    default String selfLink(Owner owner) {
49	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
50	    }
51	
52	    /** Format an owner's name as 'LastName, FirstName' for display. */
53	    default String displayName(Owner owner) {
54	        return owner.getLastName() + ", " + owner.getFirstName();
55	    }
56	
57	    /**
58	     * Compose the owner's salutation as the title, a space and the last name (e.g. 'DR Who'),
59	     * or just the last name when no title was supplied.
60	     */
61	    default String salutation(Owner owner) {
62	        String title = owner.getTitle();
63	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
