3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} maps the body to an entity. Runs first so the body is read once here
14	 * and republished for later steps. An address may be supplied in either form: a non-blank
15	 * structured {@code addressLine1}, or the flat {@code address} (judged blank after
16	 * normalization, see {@link AddressNormalizer}); a request supplying neither is rejected.
17	 */
18	public class ValidateNewOwner {
19	
20	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
21	            throws MissingOwnerFieldsException {
22	        List<String> missing = new ArrayList<>();
23	        checkPresent("firstName", request.getFirstName(), missing);
24	        checkPresent("lastName", request.getLastName(), missing);
25	        if (!hasAddress(request)) {
26	            missing.add("address");
27	        }
28	        checkPresent("city", request.getCity(), missing);
29	        checkPresent("telephone", request.getTelephone(), missing);
30	        if (!missing.isEmpty()) {
31	            throw new MissingOwnerFieldsException(missing);
32	        }
33	        validated.set(request);
34	    }
35	
36	    /** An address is present when a non-blank structured addressLine1 or a flat address is supplied. */
37	    private static boolean hasAddress(OwnerFieldsDto request) {
38	        return AddressNormalizer.isPresent(request.getAddressLine1())
39	                || !AddressNormalizer.normalize(request.getAddress()).isBlank();
40	    }
41	
42	    private static void checkPresent(String name, String value, List<String> missing) {
43	        if (value == null || value.isBlank()) {
44	            missing.add(name);
45	        }
46	    }
47	}
