2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Records whether the new owner is a suspected soft duplicate. Duplicates are caught in layers: a
10	 * hard duplicate (same {@link OwnerIdentity identity key}) is rejected by
11	 * {@link EnsureUniqueIdentity}, and a household collision (an existing owner sharing this owner's
12	 * {@link HouseholdKey household id} — same last name and postcode) is rejected as a 409 by
13	 * {@link EnsureUniqueHousehold}. This step marks the survivors: it sets {@code possibleDuplicate}
14	 * to whether an existing owner shares this owner's household id, with {@code possibleDuplicateOf}
15	 * set to that owner's id.
16	 *
17	 * <p>A declared household member ({@code sharesHousehold}) knowingly joins the household, so it is
18	 * not a suspected duplicate and stays {@code possibleDuplicate = false}.
19	 *
20	 * <p>Runs after {@link AssignHouseholdId} has set the household id and before {@link SaveOwner}
21	 * persists the entity, so {@code findAll()} sees only the owners that existed before this create.
22	 * The flags are stored on the owner and returned on every later read.
23	 */
24	public class FlagPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
27	        owner.setPossibleDuplicate(false);
28	        owner.setPossibleDuplicateOf(null);
29	
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return; // a declared household member is not a suspected duplicate
32	        }
33	        String postcode = owner.getPostcode();
34	        if (postcode == null || postcode.isBlank()) {
35	            return;
36	        }
37	        String householdId = owner.getHouseholdId();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (householdId.equals(existing.getHouseholdId())) {
40	                owner.setPossibleDuplicate(true);
41	                owner.setPossibleDuplicateOf(existing.getId());
42	                return;
43	            }
44	        }
45	    }
46	}
