42	        int points = 0;
43	        if (owner.hasEmail()) {
44	            points += EMAIL_POINTS;
45	        }
46	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
47	            points += NO_NAMESAKE_POINTS;
48	        }
49	        if (hasHousehold(owner)) {
50	            points += HOUSEHOLD_POINTS;
51	        }
