27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
31	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
32	    @Mapping(target = "initials", expression = "java(initials(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
35	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
43	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
44	    @Mapping(target = "sharesHousehold", ignore = true)
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /** The owner's canonical API path, '/api/owners/' followed by its id, or null before an id is assigned. */
48	    default String selfLink(Owner owner) {
49	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
50	    }
51	
52	    /** Format an owner's name as 'LastName, FirstName' for display. */
53	    default String displayName(Owner owner) {
54	        return owner.getLastName() + ", " + owner.getFirstName();
55	    }
56	
57	    /**
58	     * Compose the owner's salutation as the title, a space and the last name (e.g. 'DR Who'),
59	     * or just the last name when no title was supplied.
60	     */
61	    default String salutation(Owner owner) {
62	        String title = owner.getTitle();
63	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
64	    }
65	
66	    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
67	    default String initials(Owner owner) {
68	        return initial(owner.getFirstName()) + initial(owner.getLastName());
69	    }
70	
71	    private static String initial(String name) {
72	        return Character.toUpperCase(name.charAt(0)) + ".";
73	    }
74	
75	    /**
76	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
77	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
78	     * either source field is absent.
79	     */
80	    default String membershipNumber(Owner owner) {
81	        return MembershipNumbers.of(owner);
82	    }
83	
84	    /**
85	     * Derive the owner's fiscal year 'FY&lt;YY&gt;' from the (business-day-adjusted) registration
86	     * date, where the fiscal year starts on 1 July. Returns null when no registration date is set.
87	     */
88	    default String fiscalYear(Owner owner) {
89	        return FiscalYears.label(owner.getRegistrationDate());
90	    }
91	
92	    /**
93	     * Derive the Luhn check digit (0 to 9) over the digits of the owner's customer code.
94	     * Returns null when the customer code has not yet been assigned.
95	     */
96	    default Integer checkDigit(Owner owner) {
97	        if (owner.getCustomerCode() == null) {
98	            return null;
99	        }
100	        return Luhn.checkDigit(owner.getCustomerCode());
101	    }
102	
103	    /**
104	     * Derive the owner's locality (canonical region) as the region component of the customer
105	     * code identity, or 'UNKNOWN' when the code carries no region.
106	     */
107	    default String locality(Owner owner) {
108	        return CustomerCode.regionOf(owner.getCustomerCode());
109	    }
110	
111	    /**
112	     * Derive the IANA timezone name for the owner's locality (canonical region) from the fixed
113	     * region-to-timezone table, or null when the locality has no known timezone.
114	     */
115	    default String timezone(Owner owner) {
116	        return Timezones.of(locality(owner));
117	    }
118	
119	    /** Derive the owner's membership points as at the current date. */
120	    default Integer membershipPoints(Owner owner) {
121	        return MembershipLevels.pointsOf(owner, LocalDate.now());
122	    }
123	
124	    /** Derive the owner's numeric membership level (1 to 4) from the current membership points. */
125	    default Integer membershipLevel(Owner owner) {
126	        return MembershipLevels.levelFor(MembershipLevels.pointsOf(owner, LocalDate.now()));
127	    }
128	
129	    /** Derive the owner's preferred contact method: EMAIL when an email is present, otherwise PHONE. */
130	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
131	        return owner.hasEmail() ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
132	    }
133	
134	    /**
135	     * Derive the owner's age band from the birth date as at the registration date, or null
136	     * when no birth date was supplied.
137	     */
138	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
139	        AgeBand band = AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
140	        return band == null ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
141	    }
142	
143	    /** Format the owner's stored E.164 telephone for humans (e.g. '+61 412 345 678'). */
144	    default String telephoneDisplay(Owner owner) {
145	        return Telephones.forDisplay(owner.getTelephone());
146	    }
147	
148	    Owner toOwner(OwnerDto ownerDto);
149	
150	    @Mapping(target = "id", ignore = true)
151	    @Mapping(target = "pets", ignore = true)
152	    Owner toOwner(OwnerFieldsDto ownerDto);
153	
154	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
155	
