159	        OwnerPageDto ownerPageDto = new OwnerPageDto();
160	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
161	        ownerPageDto.setPage(ownerPage.getNumber());
162	        ownerPageDto.setSize(ownerPage.getSize());
163	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
164	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
165	        return ownerPageDto;
